import re
import openpyxl

def parse_position(pos):
    """Convert 'B2:C3' style to (start_col, start_row, end_col, end_row)."""
    m = re.match(r'([A-Z]+)(\d+):([A-Z]+)(\d+)', pos)
    col1, row1, col2, row2 = m.groups()
    return (openpyxl.utils.column_index_from_string(col1),
            int(row1),
            openpyxl.utils.column_index_from_string(col2),
            int(row2))

def column_letter(idx):
    return openpyxl.utils.get_column_letter(idx)

def extract_hashtags(text):
    """Return list of hashtag words (without '#') in order of appearance."""
    return re.findall(r'#(\w+)', text)

def main(spreadsheet_path, output_path, answer_pos):
    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb['Sheet1']

    start_col, start_row, end_col, end_row = parse_position(answer_pos)
    # Limits within the answer range
    max_per_row = end_col - start_col + 1

    for r in range(start_row, end_row + 1):
        tweet = ws.cell(row=r, column=1).value
        hashtags = extract_hashtags(tweet) if isinstance(tweet, str) else []
        for i, tag in enumerate(hashtags[:max_per_row]):
            ws.cell(row=r, column=start_col + i).value = tag

    wb.save(output_path)

